import { test, expect } from '@playwright/test'

test("open-artifacts", async ({ page }) => {
  // Open the Artifacts page from the navigation and stop when the artifacts library is shown.
  await page.goto("/", { waitUntil: 'domcontentloaded' })
  await expect(async () => {
    await page.getByRole("button", { name: "Artifacts", exact: true }).click()
    await expect(page).toHaveURL(new RegExp("/artifacts"), { timeout: 2000 })
  }).toPass({ timeout: 20000 })
  await expect(page).toHaveURL(new RegExp("/artifacts"))
})
